import{_ as s,o as n,a as t,b as p}from"./app.DKoEZOcr.js";const _="/ascendc.github.io/pr/5487/assets/simt_call.BL8pMLcN.png",v=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMT API","link":"/api/SIMT-API/SIMT-API"},{"text":"SIMD与SIMT混合编程简介","link":"/api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/SIMD_SIMT_hybrid_programming_intro"},{"text":"扩展语法","link":"/api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/extended_syntax/extended_syntax"},{"text":"函数执行空间限定符","link":"/api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/extended_syntax/function_execution_space_qualifier"}]},"headers":[],"relativePath":"api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/extended_syntax/function_execution_space_qualifier.md","filePath":"api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/extended_syntax/function_execution_space_qualifier.md","outlineHeaders":[{"level":2,"title":"__simt_vf__","slug":"__simt_vf__","link":"#__simt_vf__"},{"level":2,"title":"__simt_callee__","slug":"__simt_callee__","link":"#__simt_callee__"}],"lastUpdated":1787813964000}'),l={name:"api/SIMT-API/SIMD_SIMT_hybrid_programming_intro/extended_syntax/function_execution_space_qualifier.md"};function c(e,a,i,d,r,h){return n(),t("div",null,[...a[0]||(a[0]=[p('<div><article class="markdown-body"><h1>函数执行空间限定符</h1><p>SIMD与SIMT混合编程涉及多种类型的函数，它们之间遵循严格的调用关系和层级约束。本章节将会介绍整体函数类型和调用关系，并详细展开SIMT相关函数（__simt_vf__和__simt_callee__）的定义、调用语法及约束，其余限定符请参见对应章节。</p><p>SIMD与SIMT混合编程中涉及的函数类型如下表所示：</p><table><thead><tr><th>函数执行空间限定符</th><th>函数功能</th><th>调用方式</th></tr></thead><tbody><tr><td>__global__ __aicore__</td><td>算子入口，协调VF执行。若只有在AIV核内执行的SIMD与SIMT混合编程场景，可使用__global__ __vector__来标识只启动AIV核。</td><td>Host侧通过&lt;&lt;&lt;&gt;&gt;&gt;调用</td></tr><tr><td>__aicore__</td><td>Device侧辅助函数</td><td>核函数（Kernel）或同级函数调用</td></tr><tr><td>__simt_vf__</td><td>线程级并行计算任务</td><td>通过SIMT提供的asc_vf_call接口调用</td></tr><tr><td>__simd_vf__</td><td>向量级并行计算任务</td><td>通过SIMD提供的asc_vf_call接口调用</td></tr><tr><td>__simt_callee__</td><td>SIMT VF的子函数</td><td>SIMT VF内部调用</td></tr><tr><td>__simd_callee__</td><td>SIMD VF的子函数</td><td>SIMD VF内部调用</td></tr><tr><td>__callee__</td><td>编译期执行的Device侧辅助函数</td><td>Device侧函数内部均可调用</td></tr></tbody></table><p>函数调用关系如下图所示：</p><p><img src="'+_+`" alt></p><h2 id="__simt_vf__">__simt_vf__<a class="header-anchor" href="#__simt_vf__">​</a></h2><p>__simt_vf__用于标记SIMT VF入口函数，函数无返回值。使用asc_vf_call接口调用SIMT VF入口函数，启动VF子任务。函数内可使用SIMT内置变量：threadIdx、blockIdx、blockDim、gridDim。函数定义示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simt_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">function_name</span><span class="p">(</span>
<span class="w">    </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint32_t</span><span class="o">*</span><span class="w"> </span><span class="n">gm_param</span><span class="p">,</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">ubuf_param</span><span class="p">,</span>
<span class="w">    </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">scalar_param</span><span class="p">,</span><span class="w"> </span><span class="p">...);</span>
</code></pre></div><p>SIMT VF函数定义中的关键修饰符说明如下：</p><table><thead><tr><th>修饰符</th><th>作用</th></tr></thead><tbody><tr><td>__simt_vf__</td><td>函数标识符，标识SIMT VF函数。</td></tr><tr><td>inline</td><td>建议内联，实际是否内联由编译器决定。</td></tr><tr><td>__gm__</td><td>内存空间修饰符，标识内存空间为GM。</td></tr><tr><td>__ubuf__</td><td>内存空间修饰符，标识内存空间为UB。</td></tr></tbody></table><p>通过SIMT的<a href="kernel_function_config.html#asc_vf_call%E8%B0%83%E7%94%A8">asc_vf_call</a>接口在核函数（Kernel）或<code>__aicore__</code>函数中调用，调用示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">function_name</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dim3</span><span class="p">(</span><span class="n">blockDim</span><span class="p">),</span><span class="w"> </span><span class="n">arg1</span><span class="p">,</span><span class="w"> </span><span class="n">arg2</span><span class="p">,</span><span class="w"> </span><span class="p">...);</span>
</code></pre></div><p>SIMT VF函数有以下约束：</p><ul><li>入参仅支持Ascend C的<a href="builtin_data_types.html">内置数据类型</a>（int32_t、uint32_t、float、half等）及其组成的指针、数组、结构体类型，且指针类型必须指向GM或者Unified Buffer（UB）内存。</li><li>函数返回类型必须是void。</li><li>SIMT VF内只能调用__simt_callee__函数或__callee__函数。</li></ul><h2 id="__simt_callee__">__simt_callee__<a class="header-anchor" href="#__simt_callee__">​</a></h2><p>__simt_callee__子函数是SIMT VF函数内部调用的辅助函数，函数内部可以使用SIMT内置变量。定义示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__simt_callee__</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">simt_helper</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint32_t</span><span class="o">*</span><span class="w"> </span><span class="n">gm_param</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">ubuf_param</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">scalar_param</span><span class="p">,</span><span class="w"> </span><span class="p">...);</span>
</code></pre></div><p>调用示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint32_t</span><span class="w"> </span><span class="n">result</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">simt_helper</span><span class="p">(</span><span class="n">arg1</span><span class="p">,</span><span class="w"> </span><span class="n">arg2</span><span class="p">,</span><span class="w"> </span><span class="p">...);</span>
</code></pre></div><p>该函数有以下约束：</p><ul><li>入参仅支持Ascend C的<a href="builtin_data_types.html">内置数据类型</a>（int32_t、uint32_t、float、half等）及对应的指针类型。</li><li>函数返回值只能是Ascend C的<a href="builtin_data_types.html">内置数据类型</a>（int32_t、uint32_t、float、half等）及对应的指针类型。</li><li>函数内只能调用__simt_callee__函数或__callee__函数。</li></ul></article></div>`,1)])])}const m=s(l,[["render",c]]);export{v as __pageData,m as default};
